WITH valid AS (SELECT *, DATE_FORMAT(signup_date, 'yyyy-MM') AS signup_date_label, CONCAT_WS(',', name, country) AS name_country_key FROM customers WHERE signup_date >= TO_DATE('2024-02-13') AND city IS NOT NULL) SELECT s.*, latest.session_started_at, latest.session_browser FROM valid s LEFT JOIN LATERAL (SELECT c.started_at AS session_started_at, c.browser AS session_browser FROM sessions c WHERE c.customer_id = s.id ORDER BY c.started_at DESC, c.id DESC LIMIT 1) latest ON TRUE
